using System.Text.Json;
using System.Threading.RateLimiting;
using ClassPet;
using Dapper;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.HttpOverrides;
using Microsoft.AspNetCore.RateLimiting;
if(args.Contains("--healthcheck")){try{using var client=new HttpClient{Timeout=TimeSpan.FromSeconds(4)};var response=await client.GetAsync("http://127.0.0.1:8080/health/ready");Environment.Exit(response.IsSuccessStatusCode?0:1);}catch{Environment.Exit(1);}return;}
var builder=WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<Database>();builder.Services.AddSingleton<GameService>();builder.Services.AddSingleton<Accounts>();
var keyDirectory=builder.Configuration["DataProtection:Path"]??Path.Combine(builder.Environment.ContentRootPath,".data","keys");Directory.CreateDirectory(keyDirectory);builder.Services.AddDataProtection().SetApplicationName("ClassPet.Local").PersistKeysToFileSystem(new DirectoryInfo(keyDirectory));
builder.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme).AddCookie(o=>{o.Cookie.Name="ClassPet.Auth";o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Lax;o.Cookie.SecurePolicy=CookieSecurePolicy.SameAsRequest;o.ExpireTimeSpan=TimeSpan.FromDays(30);o.SlidingExpiration=false;o.Events.OnValidatePrincipal=context=>context.HttpContext.RequestServices.GetRequiredService<Accounts>().Validate(context);o.Events.OnRedirectToLogin=c=>{c.Response.StatusCode=401;return c.Response.WriteAsJsonAsync(new{error="请先登录老师账号",login=true});};o.Events.OnRedirectToAccessDenied=c=>{c.Response.StatusCode=403;return c.Response.WriteAsJsonAsync(new{error="没有操作权限"});};});
builder.Services.AddAuthorization();builder.Services.AddRateLimiter(o=>{o.RejectionStatusCode=429;o.OnRejected=async(c,ct)=>await c.HttpContext.Response.WriteAsJsonAsync(new{error="尝试次数较多，请15分钟后再试"},ct);o.AddPolicy("accounts",c=>RateLimitPartition.GetFixedWindowLimiter(c.Connection.RemoteIpAddress?.ToString()??"local",_=>new FixedWindowRateLimiterOptions{PermitLimit=30,Window=TimeSpan.FromMinutes(15),QueueLimit=0,AutoReplenishment=true}));});
builder.Services.Configure<ForwardedHeadersOptions>(o=>{o.ForwardedHeaders=ForwardedHeaders.XForwardedFor|ForwardedHeaders.XForwardedProto;o.ForwardLimit=1;o.KnownIPNetworks.Add(System.Net.IPNetwork.Parse("172.16.0.0/12"));o.KnownIPNetworks.Add(System.Net.IPNetwork.Parse("10.0.0.0/8"));o.KnownIPNetworks.Add(System.Net.IPNetwork.Parse("192.168.0.0/16"));});
builder.WebHost.ConfigureKestrel(o=>o.Limits.MaxRequestBodySize=32768);
var app=builder.Build();
app.UseForwardedHeaders();
app.Use(async(context,next)=>{try{context.Response.Headers.CacheControl="no-store";context.Response.Headers["X-Content-Type-Options"]="nosniff";if(HttpMethods.IsPost(context.Request.Method)&&context.Request.Path.StartsWithSegments("/api")){var origin=context.Request.Headers.Origin.ToString();var expected=$"{context.Request.Scheme}://{context.Request.Host}";if(!Uri.TryCreate(origin,UriKind.Absolute,out var uri)||uri.GetLeftPart(UriPartial.Authority)!=expected)throw new AppError("请求来源无效",403);if(!context.Request.HasJsonContentType())throw new AppError("请求格式无效",415);}await next();}catch(AppError e){context.Response.StatusCode=e.Status;await context.Response.WriteAsJsonAsync(new{error=e.Message});}catch(JsonException){context.Response.StatusCode=400;await context.Response.WriteAsJsonAsync(new{error="请求格式无效"});}catch(Exception e){app.Logger.LogError(e,"API request failed");context.Response.StatusCode=500;await context.Response.WriteAsJsonAsync(new{error="操作未完成，请刷新后重试"});}});
app.UseAuthentication();app.UseRateLimiter();app.UseAuthorization();
app.MapGet("/health/ready",async(Database db)=>{await using var c=db.Open();await c.OpenAsync();await c.ExecuteScalarAsync<int>("SELECT 1");return Results.Ok(new{status="ok"});});
app.MapPost("/api/account",async(HttpContext context,Accounts accounts)=>{var body=await context.Request.ReadFromJsonAsync<JsonElement>();if(body.ValueKind!=JsonValueKind.Object)throw new AppError("请求格式无效");return Results.Json(await accounts.Act(context,body));}).RequireRateLimiting("accounts");
app.MapGet("/api/state",async(HttpContext context,GameService game)=>{var id=Accounts.TeacherId(context.User);var classId=context.Request.Query["classId"].ToString();if(context.Request.Query["export"]=="1"){var result=await game.Export(id,classId);return Results.File(JsonSerializer.SerializeToUtf8Bytes(result,new JsonSerializerOptions{WriteIndented=true,PropertyNamingPolicy=JsonNamingPolicy.CamelCase}),"application/json","classpet-backup.json");}var state=await game.State(id,classId,context.Request.Query["seatId"].ToString());return Results.Json(new{data=state,user=new{name=context.User.Identity!.Name},account=new{kind="local",username=context.User.Identity.Name}});}).RequireAuthorization();
app.MapPost("/api/action",async(HttpContext context,GameService game)=>{var body=await context.Request.ReadFromJsonAsync<JsonElement>();if(body.ValueKind!=JsonValueKind.Object)throw new AppError("请求格式无效");return Results.Json(await game.Act(Accounts.TeacherId(context.User),body,context.Request.Headers["Idempotency-Key"].ToString()));}).RequireAuthorization();
for(int attempt=0;;attempt++){try{await app.Services.GetRequiredService<Database>().Initialize();break;}catch(Exception e)when(attempt<9){app.Logger.LogWarning("MySQL not ready ({Attempt}/10): {Message}",attempt+1,e.Message);await Task.Delay(TimeSpan.FromSeconds(2));}}
await app.RunAsync();
